layout_css:
.guide-container {
  max-width: 720px;
  margin: 0 auto;
}
.guide-progress-bar {
  width: 100%;
  height: 10px;
  background: rgba(148, 163, 184, 0.25);
  border-radius: 999px;
  overflow: hidden;
  margin: 16px 0 24px;
}
.guide-progress-fill {
  height: 100%;
  width: 0%;
  background: #2563eb;
  transition: width 0.3s ease;
}
.guide-step-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.guide-step-card {
  border: 2px solid rgba(148, 163, 184, 0.35);
  border-radius: 12px;
  padding: 16px;
  transition: all 0.2s ease;
  cursor: pointer;
}
.guide-step-card.is-locked {
  opacity: 0.45;
  cursor: not-allowed;
  filter: grayscale(0.6);
}
.guide-step-card.is-completed {
  border-color: #10b981;
  background: rgba(16, 185, 129, 0.08);
}
.guide-step-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 800;
}
.guide-step-detail {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px dashed rgba(148, 163, 184, 0.4);
  font-size: 14px;
  line-height: 1.6;
}
